// Fixed checks, no AI: each of these has one right answer, so plain code checks it.
const draft = $json.body || {};
const subject = String(draft.subject || '');
const preview = String(draft.preheader || '');
const html = String(draft.html || '');
const blockers = [];
const warnings = [];
const flag = (list, category, issue, fix) => list.push({ category, issue, fix });

// 1. First-name tags need a real fallback, unless they sit inside {% if first_name %} ... {% endif %}.
const outsideIfs = html.replace(/\{%\s*if[\s\S]*?\{%\s*endif\s*%\}/g, '');
for (const tag of outsideIfs.match(/\{\{[^}]*\}\}/g) || []) {
  if (/first_?name/i.test(tag) && !/default[:(]\s*['"][^'"]+['"]/.test(tag)) {
    flag(blockers, 'personalization', tag + ' has no fallback, or an empty one.', 'Use {% if first_name %} {{ first_name }}{% endif %} or a real fallback.');
  }
}

// 2. Links: https, with lowercase utm_source, utm_medium=email and utm_campaign.
//    Unsubscribe links and links built from template tags are skipped.
for (const [, url] of html.matchAll(/href="([^"]*)"/gi)) {
  if (/unsubscribe|manage_preferences|\{[{%]/i.test(url)) continue;
  if (!/^https:\/\//i.test(url)) {
    flag(blockers, 'links', 'Link "' + url + '" is empty, a placeholder or not https.', 'Use the full https URL.');
    continue;
  }
  const utm = (name) => (url.match(new RegExp('[?&]utm_' + name + '=([^&#]*)')) || [])[1];
  const values = ['source', 'medium', 'campaign'].map(utm);
  if (values.some((v) => !v || v !== v.toLowerCase()) || utm('medium') !== 'email') {
    flag(blockers, 'utm', url + ' lacks lowercase utm_source, utm_medium=email or utm_campaign.', 'Add ?utm_source=klaviyo&utm_medium=email&utm_campaign=<lowercase_name>.');
  }
}

// 3. The unsubscribe tag must be there.
if (!/unsubscribe/i.test(html)) {
  flag(blockers, 'unsubscribe', 'No unsubscribe tag or link.', 'Add {% unsubscribe %} (Klaviyo) or {{ unsubscribe_link }} (HubSpot).');
}

// 4. Phones cut subjects near 50 characters; the preview text should add something.
const length = [...subject].length;
if (length > 50) {
  flag(warnings, 'mobile_ux', 'The subject is ' + length + ' characters; phones cut it near 50.', 'Trim it to 50 characters or fewer.');
}
if (!preview.trim() || preview.trim() === subject.trim()) {
  flag(warnings, 'preview_text', 'The preview text is empty or repeats the subject.', 'Add one line the subject does not already say.');
}

// 5. Images need alt text.
const noAlt = (html.match(/<img\b(?![^>]*\balt="[^"]+")[^>]*>/gi) || []).length;
if (noAlt) {
  flag(warnings, 'accessibility', noAlt + ' image(s) without alt text.', 'Describe each image in its alt attribute.');
}

return { json: { rule_blockers: blockers, rule_warnings: warnings } };

// One verdict: the fixed-rule results first, then the AI's policy check.
const rules = $('Rules: Fixed Checks (No AI)').item.json;
const raw = String(
  $json.choices?.[0]?.message?.content ||
  $json.candidates?.[0]?.content?.parts?.[0]?.text ||
  ''
).replace(/```json|```/g, '').trim();

let parsed = null;
try {
  parsed = JSON.parse(raw);
} catch (err) {
  parsed = null;
}

const ok = parsed && typeof parsed === 'object';
const aiBlockers = ok && Array.isArray(parsed.blockers) ? parsed.blockers : [];
const aiWarnings = ok && Array.isArray(parsed.warnings) ? parsed.warnings : [];
if (!ok) {
  aiBlockers.push({
    category: 'qa_engine_error',
    issue: 'AI policy check could not be parsed cleanly',
    fix: 'Re-run Pre-Flight QA or check API credentials before scheduling.'
  });
}

const blockers = [...(rules.rule_blockers || []), ...aiBlockers];
const warnings = [...(rules.rule_warnings || []), ...aiWarnings];
return {
  json: {
    status: blockers.length ? 'FAIL' : 'PASS',
    has_discount_offer: Boolean(ok && parsed.has_discount_offer),
    blockers,
    warnings
  }
};

